/// </summary>
class METSalesOrderLoadPlanningController extends SrsReportRunController
{
    METSalesOrderLoadPlanningContract salesLoadPlanningAidContract;
}

Method.Source:
public static METSalesOrderLoadPlanningController construct()
{
    return new METSalesOrderLoadPlanningController();
}

public static void sendMailReport(InventLocation _inventLocation, SalesTable _salesTable)
{
    if (!_inventLocation)
    {
        throw Error("The warehouse does not contain an email address");
    }

    SrsReportRunController controller = new SrsReportRunController();

    controller.parmReportName(ssrsReportStr(METTransferOrderLoadPlanningReport, LoadReport));
    controller.parmShowDialog(false);
    controller.parmDialogCaption("@MET:SODTOLoadPlanReport");

    METTransferOrderLoadPlanningContract contract = controller.parmReportContract().parmRdpContract() as METTransferOrderLoadPlanningContract;
    contract.parmConfirmedShipDateFrom(systemDateGet());
    contract.parmConfirmedShipDateTo(systemDateGet());
    controller.parmReportContract().parmRdpContract(contract);

    SRSPrintDestinationSettings settings = controller.parmReportContract().parmPrintSettings();

    settings.printMediumType(SRSPrintMediumType::Email);
    settings.fileFormat(SRSReportFileFormat::PDF);
    settings.fileName('SysUserRoleInfo.pdf');

    // Here we configure the email
    SrsReportEMailDataContract emailContract = new SrsReportEMailDataContract();

    emailContract.parmTo("merinna@metcash.com");
    emailContract.parmSubject("Security report");
    emailContract.parmBody("Hi there! Here is your report.");

    settings.parmEMailContract(emailContract);

    controller.startOperation();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    InventLocation inventLocation;
    SalesTable salesTable;
    METSalesOrderLoadPlanningController::sendMailReport(inventLocation, salesTable);
